void require(bool v,const char* s){if(!v)throw std::runtime_error(s);}
struct V {float x,y,z;};
V add(V a,V b){return {a.x+b.x,a.y+b.y,a.z+b.z};} V mul(V a,float s){return {a.x*s,a.y*s,a.z*s};} float dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;} V cross(V a,V b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};} V norm(V a){float d=std::sqrt(dot(a,a));require(d>1e-8f&&std::isfinite(d),"CPU reference nondegenerate");return mul(a,1.f/d);}
u32 packed(float x,float y){auto q=[](float n){return u32(std::clamp<long>(std::lround((n+1.f)*.5f*65535.f),0,65535));};return (q(x)<<16)|q(y);}
V unpack(u32 p,bool positive,bool clampOverflow=false){float x=float(p>>16)*(2.f/65535.f)-1.f,y=float(p&65535)*(2.f/65535.f)-1.f;float d=x*x+y*y;if(d>1.f)return clampOverflow?norm({x,y,0}):V{0,0,1};return {x,y,std::sqrt(std::max(0.f,1.f-d))*(positive?1.f:-1.f)};}
struct Case {const char* name;float nx,tx;u32 bits;bool flip;float u,v;float ny=0,ty=0;bool overflow=false;};
// texel coordinate (0,0),(1,0),(0,1),(1,1), linear UNORM.
constexpr u8 normalPixels[16]={191,160,238,255, 150,210,220,255, 205, 90,224,255, 100,170,240,255};
V expected(const Case& c,bool tzCorrect,bool handCorrect,bool correctOverflow=false){
 V N=norm(unpack(packed(c.nx,c.ny),c.bits&2)); V T0=norm(unpack(packed(c.tx,c.ty),c.bits&(tzCorrect?4:2),correctOverflow)); V T=std::abs(dot(T0,N))>.999f?norm(cross(std::abs(N.y)<.999f?V{1,0,0}:V{0,1,0},N)):norm(add(T0,mul(N,-dot(T0,N))));
 // Identity projection uses Naga's explicit clip-Y inversion and positive
 // Vulkan viewport. proj X=-1 reverses dpdx and hence cross(dpdy,dpdx).
 V geom={0,0,c.flip?-1.f:1.f};if(dot(N,geom)<0)N=mul(N,-1);
 V B=norm(cross(N,T));if(handCorrect&&(c.bits&1)) B=mul(B,-1);
 // Constant vertex UV; production VS uses (u,1-v), fixed texel centers.
 int x=c.u<.5f?0:1, y=(1.f-c.v)<.5f?0:1;auto* p=normalPixels+(y*2+x)*4;
 V sample={p[0]/255.f*2-1,p[1]/255.f*2-1,p[2]/255.f*2-1};return norm(add(add(mul(T,sample.x),mul(B,sample.y)),mul(N,sample.z)));
}
