int main(int argc,char**argv){try{std::string vs,fs,variant;for(int i=1;i<argc;++i){require(i+1<argc,"expected value");std::string a=argv[i],v=argv[++i];if(a=="--vs")vs=v;else if(a=="--fs")fs=v;else if(a=="--variant")variant=v;else throw std::runtime_error("unknown option");}require(!vs.empty()&&!fs.empty()&&(variant=="baseline"||variant=="tangent-z"||variant=="tangent-z-hand"||variant=="tangent-z-hand-clamp"),"usage --vs path --fs path --variant baseline|tangent-z|tangent-z-hand|tangent-z-hand-clamp");Fixture f(vs,fs);f.init();const Case cases[]={
 {"Nneg_Tpos_front_bit0_clear",.8f,.6f,4,false,.25f,.25f},{"Nneg_Tpos_back_bit0_clear",.8f,.6f,4,true,.25f,.25f},
 {"Npos_Tneg_front",.8f,.6f,2,false,.25f,.25f},{"Npos_Tneg_back",.8f,.6f,2,true,.25f,.25f},
 {"same_sign_control",.8f,-.6f,6,false,.25f,.25f},{"hand_bit0_set",.8f,.6f,5,false,.25f,.25f},
 {"hand_bit0_clear_uv_mirror",.8f,.6f,4,false,.75f,.25f},{"hand_bit0_set_uv_mirror",.8f,.6f,5,false,.75f,.25f},
 {"asymmetric_v_flip",.8f,.6f,4,false,.25f,.75f},{"hand_flip_back",.8f,.6f,5,true,.25f,.75f},
 {"quantized_xy_unit_circle_overflow",0,.6f,6,false,.25f,.25f,0,.8f,true}};
 unsigned pass=0,xfail=0;for(const auto& c:cases){auto actual=f.run(c);V ref=expected(c,true,true,true),model=expected(c,variant!="baseline",variant=="tangent-z-hand"||variant=="tangent-z-hand-clamp",variant=="tangent-z-hand-clamp");auto enc=[](float v){return int(std::clamp<long>(std::lround((v*.5f+.5f)*255.f),0,255));};int modelErr=0,contractErr=0;int m[]={enc(model.x),enc(model.y),enc(model.z)},r[]={enc(ref.x),enc(ref.y),enc(ref.z)};for(int i=0;i<3;++i){modelErr=std::max(modelErr,std::abs(int(actual[i])-m[i]));contractErr=std::max(contractErr,std::abs(int(actual[i])-r[i]));}bool anticipated=std::max({std::abs(m[0]-r[0]),std::abs(m[1]-r[1]),std::abs(m[2]-r[2])})>2;std::cout<<"[TANGENT_FRAME] "<<c.name<<" mode="<<variant<<" rgba="<<int(actual[0])<<","<<int(actual[1])<<","<<int(actual[2])<<","<<int(actual[3])<<" model_error="<<modelErr<<" contract_error="<<contractErr<<" expected_contract="<<(anticipated?"XFAIL":"PASS")<<std::endl;require(modelErr<=2&&actual[3]==255,"GPU vs quantified variant reference exceeds 2 UNorm8 codes");if(anticipated){require(contractErr>2,"expected deficiency did not manifest");++xfail;}else{require(contractErr<=2,"contract reference exceeds 2 UNorm8 codes");++pass;}}require(pass>0,"positive control");if(variant!="tangent-z-hand-clamp")require(xfail>0,"missing expected failing controls");std::cout<<"[TANGENT_FRAME] PASS="<<pass<<" XFAIL="<<xfail<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"[TANGENT_FRAME] ERROR "<<e.what()<<std::endl;return 1;}}
